    fn to_planes_query(
        value: &PlanesQuery,
        inputs: &mut Inputs,
    ) -> Result<sys::PlanesQuery> {
        let native_planes = {
            if value.planes.len() != 6 {
                return Err(ApiError::new(ErrorCode::InvalidArgument as i32));
            }
            let mut converted = Vec::with_capacity(6);
            for item in value.planes.iter() {
                converted.push(to_float4(item, inputs)?);
            }
            converted
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::InvalidArgument as i32))?
        };
        let native_plane_count = value.plane_count as _;
        Ok(sys::PlanesQuery {
            planes: native_planes,
            planeCount: native_plane_count,
        })
    }
    fn to_float4(value: &Float4, _inputs: &mut Inputs) -> Result<sys::Float4> {
        let native_x = value.x as _;
        let native_y = value.y as _;
        let native_z = value.z as _;
        let native_w = value.w as _;
        Ok(sys::Float4 {
            x: native_x,
            y: native_y,
            z: native_z,
            w: native_w,
        })
    }
    fn from_float3(value: &sys::Float3) -> Result<Float3> {
        Ok(Float3 {
            x: (value.x) as _,
            y: (value.y) as _,
            z: (value.z) as _,
        })
    }
