    pub(crate) fn get_ground_heights(
        engine: &crate::Backend<'_>,
        positions: &[f32],
    ) -> Result<Vec<f32>> {
        let mut inputs = Inputs::default();
        let native_positions = {
            let mut converted: Vec<f32> = Vec::with_capacity((positions).len());
            for item in (positions).iter() {
                converted.push(*(item) as _);
            }
            inputs.slice(converted) as _
        };
        let query = sys::GetGroundHeightsQuery {
            positions: native_positions,
            count: (positions)
                .len()
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::OutOfBounds as i32))?,
        };
        let table = unsafe { (engine.raw()).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let table = unsafe { (table.terrain).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let call = table
            .GetGroundHeights
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let mut result = core::mem::MaybeUninit::<sys::GetGroundHeightsResult>::zeroed();
        unsafe {
            call(&query, result.as_mut_ptr());
        }
        let result = unsafe { result.assume_init() };
        unsafe {
            check_error(result.error)?;
        }
        unsafe { read_slice(result.heights, result.count as usize)? }
            .iter()
            .map(|item| -> Result<_> { Ok((*item) as _) })
            .collect::<Result<Vec<_>>>()
    }
