    fn from_config_param(value: &sys::ConfigParam) -> Result<ConfigParam> {
        Ok(ConfigParam {
            name: unsafe { read_string(value.name, None)? },
            type_: match (value.type_) as i64 {
                3 => ConfigValueType::ConfigTypeBool,
                1 => ConfigValueType::ConfigTypeFloat,
                0 => ConfigValueType::ConfigTypeInt,
                2 => ConfigValueType::ConfigTypeString,
                _ => return Err(ApiError::new(ErrorCode::InvalidState as i32)),
            },
            description: unsafe { read_string(value.description, None)? },
            default_value: unsafe { read_string(value.defaultValue, None)? },
            minimum_value: unsafe { read_string(value.minimumValue, None)? },
            maximum_value: unsafe { read_string(value.maximumValue, None)? },
            read_only: (value.readOnly) as _,
        })
    }
