        let native_test_objects = value.test_objects as _;
        let native_center_only = value.center_only as _;
        Ok(sys::TestMoveOrderOptions {
            testTerrain: native_test_terrain,
            testObjects: native_test_objects,
            centerOnly: native_center_only,
        })
