    pub(crate) fn active_fbo<
        E: crate::Environment,
        F: for<'call> FnMut(&mut crate::Spring<'call, E>),
    >(
        engine: &crate::Backend<'_>,
        fbo_id: u32,
        target: u32,
        identities: bool,
        callback: F,
    ) -> Result<()> {
        super::invoke_sync::<
            E,
            _,
            _,
        >(
            engine,
            callback,
            |callback, user_data| {
                let native_fbo_id = (fbo_id) as _;
                let native_target = (target) as _;
                let native_identities = (identities) as _;
                let query = sys::GfxActiveFBOQuery {
                    fboID: native_fbo_id,
                    target: native_target,
                    identities: native_identities,
                    callback,
                    userData: user_data,
                };
                let table = unsafe { (engine.raw()).as_ref() }
                    .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
                let table = unsafe { (table.gfx).as_ref() }
                    .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
                let call = table
                    .ActiveFBO
                    .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
                let mut result = core::mem::MaybeUninit::<sys::GfxEmptyResult>::zeroed();
                unsafe {
                    call(&query, result.as_mut_ptr());
                }
                let result = unsafe { result.assume_init() };
                unsafe {
                    check_error(result.error)?;
                }
                Ok(())
            },
        )
    }
