    pub(crate) fn create_fbo(
        engine: &crate::Backend<'_>,
        target: u32,
        attachments: &[GfxFBOAttachment],
        draw_buffers: &[u32],
        read_buffer: u32,
    ) -> Result<CreateFBOValue> {
        let mut inputs = Inputs::default();
        let native_target = (target) as _;
        let native_attachments = {
            let mut converted: Vec<sys::GfxFBOAttachment> = Vec::with_capacity(
                (attachments).len(),
            );
            for item in (attachments).iter() {
                converted.push(to_gfx_fbo_attachment(item, &mut inputs)?);
            }
            inputs.slice(converted) as _
        };
        let native_draw_buffers = {
            let mut converted: Vec<u32> = Vec::with_capacity((draw_buffers).len());
            for item in (draw_buffers).iter() {
                converted.push(*(item) as _);
            }
            inputs.slice(converted) as _
        };
        let native_read_buffer = (read_buffer) as _;
        let query = sys::GfxFBOCreateQuery {
            target: native_target,
            attachments: native_attachments,
            attachmentCount: (attachments)
                .len()
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::OutOfBounds as i32))?,
            drawBuffers: native_draw_buffers,
            drawBufferCount: (draw_buffers)
                .len()
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::OutOfBounds as i32))?,
            readBuffer: native_read_buffer,
        };
        let table = unsafe { (engine.raw()).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let table = unsafe { (table.gfx).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let call = table.CreateFBO.ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let mut result = core::mem::MaybeUninit::<sys::GfxFBOResult>::zeroed();
        unsafe {
            call(&query, result.as_mut_ptr());
        }
        let result = unsafe { result.assume_init() };
        unsafe {
            check_error(result.error)?;
        }
        Ok(CreateFBOValue {
            fbo_id: (result.fboID) as _,
            raw_id: (result.rawID) as _,
        })
    }
