    pub(crate) fn solve_nurbs_curve(
        engine: &crate::Backend<'_>,
        degree: i32,
        points: &[Float4],
        knots: &[f32],
        segments: i32,
    ) -> Result<SolveNURBSCurveValue> {
        let mut inputs = Inputs::default();
        let native_degree = (degree) as _;
        let native_points = {
            let mut converted: Vec<sys::Float4> = Vec::with_capacity((points).len());
            for item in (points).iter() {
                converted.push(to_float4(item, &mut inputs)?);
            }
            inputs.slice(converted) as _
        };
        let native_knots = {
            let mut converted: Vec<f32> = Vec::with_capacity((knots).len());
            for item in (knots).iter() {
                converted.push(*(item) as _);
            }
            inputs.slice(converted) as _
        };
        let native_segments = (segments) as _;
        let query = sys::SolveNURBSCurveQuery {
            degree: native_degree,
            points: native_points,
            pointCount: (points)
                .len()
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::OutOfBounds as i32))?,
            knots: native_knots,
            knotCount: (knots)
                .len()
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::OutOfBounds as i32))?,
            segments: native_segments,
        };
        let table = unsafe { (engine.raw()).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let table = unsafe { (table.unsyncedRead).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let call = table
            .SolveNURBSCurve
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let mut result = core::mem::MaybeUninit::<sys::SolveNURBSCurveResult>::zeroed();
        unsafe {
            call(&query, result.as_mut_ptr());
        }
        let result = unsafe { result.assume_init() };
        unsafe {
            check_error(result.error)?;
        }
        Ok(SolveNURBSCurveValue {
            points: unsafe { read_slice(result.points, result.count as usize)? }
                .iter()
                .map(|item| -> Result<_> { from_float3(item) })
                .collect::<Result<Vec<_>>>()?,
            success: (result.success) as _,
        })
    }
    fn to_float4(value: &Float4, _inputs: &mut Inputs) -> Result<sys::Float4> {
        let native_x = value.x as _;
        let native_y = value.y as _;
        let native_z = value.z as _;
        let native_w = value.w as _;
        Ok(sys::Float4 {
            x: native_x,
            y: native_y,
            z: native_z,
            w: native_w,
        })
    }
    fn from_active_command_description(
        value: &sys::ActiveCommandDescription,
    ) -> Result<ActiveCommandDescription> {
        Ok(ActiveCommandDescription {
            id: (value.id) as _,
            type_: (value.type_) as _,
            name: unsafe { read_string(value.name, None)? },
            action: unsafe { read_string(value.action, None)? },
            tooltip: unsafe { read_string(value.tooltip, None)? },
            texture: unsafe { read_string(value.texture, None)? },
            cursor: unsafe { read_string(value.cursor, None)? },
            queueing: (value.queueing) as _,
            hidden: (value.hidden) as _,
            disabled: (value.disabled) as _,
            show_unique: (value.showUnique) as _,
            only_texture: (value.onlyTexture) as _,
            params: unsafe { read_slice(value.params, value.paramCount as usize)? }
                .iter()
                .map(|item| -> Result<_> { Ok(unsafe { read_string(*item, None)? }) })
                .collect::<Result<Vec<_>>>()?,
        })
    }
    fn from_float3(value: &sys::Float3) -> Result<Float3> {
        Ok(Float3 {
            x: (value.x) as _,
            y: (value.y) as _,
            z: (value.z) as _,
        })
    }
