    fn to_native_command(
        value: &NativeCommand,
        inputs: &mut Inputs,
    ) -> Result<sys::NativeCommand> {
        let native_cmd_id = value.cmd_id as _;
        let native_params = {
            let mut converted: Vec<f32> = Vec::with_capacity(value.params.len());
            for item in value.params.iter() {
                converted.push(*(item) as _);
            }
            inputs.slice(converted) as _
        };
        let native_options = value.options as _;
        let native_timeout = value.timeout as _;
        Ok(sys::NativeCommand {
            cmdID: native_cmd_id,
            params: native_params,
            paramCount: value
                .params
                .len()
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::OutOfBounds as i32))?,
            options: native_options,
            timeout: native_timeout,
        })
    }
