    pub(crate) fn set_feature_piece_matrix(
        engine: &crate::Backend<'_>,
        feature_id: i32,
        piece_index: i32,
        matrix: &[f32],
    ) -> Result<bool> {
        let native_feature_id = (feature_id) as _;
        let native_piece_index = (piece_index) as _;
        let native_matrix = {
            if (matrix).len() != 16 {
                return Err(ApiError::new(ErrorCode::InvalidArgument as i32));
            }
            let mut converted = Vec::with_capacity(16);
            for item in (matrix).iter() {
                converted.push(*(item) as _);
            }
            converted
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::InvalidArgument as i32))?
        };
        let query = sys::SetFeaturePieceMatrixQuery {
            featureID: native_feature_id,
            pieceIndex: native_piece_index,
            matrix: native_matrix,
        };
        let table = unsafe { (engine.raw()).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let table = unsafe { (table.syncedCtrl).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let table = unsafe { (table.feature).as_ref() }
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let call = table
            .SetFeaturePieceMatrix
            .ok_or(ApiError::new(ErrorCode::NotAvailable as i32))?;
        let mut result = core::mem::MaybeUninit::<
            sys::SetFeaturePieceMatrixResult,
        >::zeroed();
        unsafe {
            call(&query, result.as_mut_ptr());
        }
        let result = unsafe { result.assume_init() };
        unsafe {
            check_error(result.error)?;
        }
        Ok((result.blockScriptAnims) as _)
    }
