    fn to_object_material_descriptor(
        value: &ObjectMaterialDescriptor,
        inputs: &mut Inputs,
    ) -> Result<sys::ObjectMaterialDescriptor> {
        let native_shader_id = value.shader_id as _;
        let native_shader = inputs.string(&value.shader)? as _;
        let native_order = value.order as _;
        let native_use_camera = value.use_camera as _;
        let native_culling = value.culling as _;
        let native_texture_units = {
            let mut converted: Vec<u32> = Vec::with_capacity(value.texture_units.len());
            for item in value.texture_units.iter() {
                converted.push(*(item) as _);
            }
            inputs.slice(converted) as _
        };
        let native_texture_names = {
            let mut converted: Vec<*const i8> = Vec::with_capacity(
                value.texture_names.len(),
            );
            for item in value.texture_names.iter() {
                converted.push(inputs.string(item)? as _);
            }
            inputs.slice(converted) as _
        };
        let native_pre_list = value.pre_list as _;
        let native_post_list = value.post_list as _;
        Ok(sys::ObjectMaterialDescriptor {
            shaderID: native_shader_id,
            shader: native_shader,
            order: native_order,
            useCamera: native_use_camera,
            culling: native_culling,
            textureUnits: native_texture_units,
            textureNames: native_texture_names,
            textureCount: value
                .texture_names
                .len()
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::OutOfBounds as i32))?,
            preList: native_pre_list,
            postList: native_post_list,
        })
    }
    fn to_object_material_uniform(
        value: &ObjectMaterialUniform,
        inputs: &mut Inputs,
    ) -> Result<sys::ObjectMaterialUniform> {
        let native_name = inputs.string(&value.name)? as _;
        let native_type_ = value.type_ as _;
        let native_float_values = {
            if value.float_values.len() != 32 {
                return Err(ApiError::new(ErrorCode::InvalidArgument as i32));
            }
            let mut converted = Vec::with_capacity(32);
            for item in value.float_values.iter() {
                converted.push(*(item) as _);
            }
            converted
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::InvalidArgument as i32))?
        };
        let native_int_values = {
            if value.int_values.len() != 32 {
                return Err(ApiError::new(ErrorCode::InvalidArgument as i32));
            }
            let mut converted = Vec::with_capacity(32);
            for item in value.int_values.iter() {
                converted.push(*(item) as _);
            }
            converted
                .try_into()
                .map_err(|_| ApiError::new(ErrorCode::InvalidArgument as i32))?
        };
        let native_value_count = value.value_count as _;
        Ok(sys::ObjectMaterialUniform {
            name: native_name,
            type_: native_type_,
            floatValues: native_float_values,
            intValues: native_int_values,
            valueCount: native_value_count,
        })
    }
